-- Emoji picker -----------------------------------------------------
-- XKB keycode 60 is the physical '.' key on the normal keyboard row.
-- Use Quickshell's native Hyprland global-shortcut protocol instead of
-- spawning `qs ipc ...` every time SUPER + . is pressed.
hl.bind(
    "SUPER + code:60",
    hl.dsp.global("quickshell:emoji")
)

-- Find My Mouse ----------------------------------------------------
-- Modifier-only binds in Hyprland Lua require the target modifier mask plus
-- the real XKB keysym (Control_L / Control_R) and a release bind.
--
-- We deliberately do NOT use hl.dsp.global() for Ctrl itself. Modifier-only
-- global-shortcut dispatch has had edge cases in Hyprland, while a normal Lua
-- callback is reliable. The first Ctrl release only arms a 420 ms timer; the
-- second release inside that window launches the already-tested Quickshell IPC.
-- Therefore normal Ctrl usage does not spawn a process on every key press.

local findMouseTapPending = false
local findMouseTapTimer = nil

local function clearFindMouseTap()
    findMouseTapPending = false
    findMouseTapTimer = nil
end

local function registerFindMouseCtrlTap()
    if findMouseTapPending then
        findMouseTapPending = false

        if findMouseTapTimer ~= nil then
            findMouseTapTimer:set_enabled(false)
            findMouseTapTimer = nil
        end

        -- hl.exec_cmd() is asynchronous, so this does not block Hyprland's
        -- compositor/input event loop.
        hl.exec_cmd("qs ipc call findMouse trigger")
        return
    end

    findMouseTapPending = true
    findMouseTapTimer = hl.timer(function()
        clearFindMouseTap()
    end, {
        timeout = 420,
        type = "oneshot"
    })
end

hl.bind(
    "CTRL + Control_L",
    registerFindMouseCtrlTap,
    { release = true, non_consuming = true }
)

hl.bind(
    "CTRL + Control_R",
    registerFindMouseCtrlTap,
    { release = true, non_consuming = true }
)

-- AI Selection ----------------------------------------------------
-- A short SUPER + left click opens AI Selection. Holding the button and
-- dragging beyond the threshold moves the window instead. The gestures
-- share the same button but use different handlers; never combine the
-- `mouse` option with `click` or `drag` (those imply key release and
-- Hyprland rejects that combination as "mouse is exclusive").
--
-- Both main Hyprland configurations load this file after their default
-- mouse binds. Remove those defaults before installing the shared gestures.
-- Do not modify the separate Quickshell shell or Xavion.

hl.on("hyprland.start", function()
    hl.exec_cmd("qs -p ~/.config/quickshell/ai-selection")
end)

-- Movement of 12 pixels or more is a drag. Small movement is still a click.
-- If accidental activations occur, increase this value to 15-18.
hl.config({ binds = { drag_threshold = 12 } })

-- Clear the old SUPER + LMB movement bind from hyprland.lua and the old
-- SUPER + SHIFT + LMB workaround introduced by AI Selection v0.2.
hl.unbind("SUPER + mouse:272")
hl.unbind("SUPER + SHIFT + mouse:272")

-- Clicks are evaluated on button release, provided the pointer stays
-- within the movement threshold. Mark this binding transparent so the
-- mouse-movement binding below cannot shadow it.
hl.bind(
    "SUPER + mouse:272",
    hl.dsp.exec_cmd("qs ipc -p ~/.config/quickshell/ai-selection call aiselection open"),
    { click = true, transparent = true }
)

-- Dragging remains a real interactive Hyprland move operation, starting
-- when the pointer has moved past drag_threshold while LMB is held.
hl.bind(
    "SUPER + mouse:272",
    hl.dsp.window.drag(),
    { mouse = true }
)

